/* =======================================================
   VEHICLE INTELLIGENCE and FLEET FORECAST
   ======================================================= */

export function getVehicleIntelligence(
  vehicle: FlipRecord,
  buyer: any,
  ai: any
): VehicleIntelligence {

  const match = matchEngine.evaluate(vehicle, buyer, ai);

  const motRisk = ai.motRiskScore ? ai.motRiskScore(vehicle) : (ai.motRiskScore ?? (() => 0))(vehicle);
  const profitForecast = ai.profitForecast ? ai.profitForecast(vehicle) : 0;
  const aiPrice = ai.priceVehicle ? ai.priceVehicle(vehicle) : (vehicle.aiPrice?.recommendedSellPrice ?? vehicle.valuation ?? 0);
  const flipAdvice = ai.flipAdvice ? ai.flipAdvice(vehicle) : "Standard flip";
  const autoListing = ai.autoWriteListing ? ai.autoWriteListing(vehicle) : (vehicle.title ?? "Listing");

  return {
    matchScore: match.score,
    matchBand: match.band,
    motRiskPercent: Math.round(motRisk),
    profitForecast,
    aiPriceSuggestion: aiPrice,
    flipAdvice,
    autoListing,
  };
}

export function getMotAiIntelligence(vehicle: FlipRecord): MotAiIntelligence {
  return motAiEngine(vehicle.mot ?? {}, [{ mileage: vehicle.mileage ?? 0 }]);
}

